import{e as i,ab as r,a1 as s,m as l,j as e,q as t,r as n,p as d}from"./chunks/framework.BGh0NSIy.js";const y=JSON.parse('{"title":"Monthly Updates [December] 250k members!!","description":"Thank you all for 250K members! ♡","frontmatter":{"title":"Monthly Updates [December] 250k members!!","description":"Thank you all for 250K members! ♡","date":"2023-12-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/dec-2023.md","filePath":"posts/dec-2023.md"}'),p={name:"posts/dec-2023.md"};function h(m,a,c,f,u,g){const o=r("Post");return s(),l("div",null,[a[0]||(a[0]=e("div",{class:"info custom-block"},[e("p",{class:"custom-block-title"},"INFO"),e("p",null,[t("These update threads only contain major updates. If you're interested in seeing all minor changes you can follow our "),e("a",{href:"https://github.com/fmhy/FMHYedit/commits/main",target:"_blank",rel:"noreferrer"},"Commits Page"),t(" on GitHub or "),e("a",{href:"https://redd.it/17f8msf",target:"_blank",rel:"noreferrer"},"Updates Channel"),t(" in Discord.")])],-1)),n(o,{authors:"nbats,taskylizard"}),a[1]||(a[1]=d('<hr><h3 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h3><ul><li><p>Separated Tool sections into their own pages: <a href="/system-tools">System Tools</a>, <a href="/file-tools">File Tools</a>, <a href="/internet-tools">Internet Tools</a>, <a href="/text-tools">Text Tools</a>, <a href="/video-tools">Video Tools</a> and <a href="/audio-tools">Audio Tools</a>.</p></li><li><p>Separated Health into subsections: <a href="/misc#mental-health">Mental</a>, <a href="/misc#physical-health">Physical</a>, <a href="/misc#nutritional-health">Nutritional</a>, <a href="/misc#sexual-health">Sexual</a> and <a href="/misc#detoxing">Detoxing</a>.</p></li><li><p>Added a section for <a href="/gaming#open-source-games">Open-Source Games</a> in Gaming.</p></li><li><p>Added a section for <a href="/video-tools#animation-tools">Animation Tools</a> in Video Tools.</p></li><li><p>Added a section for <a href="/reading#academic-papers">Academic Papers</a> in Educational Reading.</p></li><li><p>Added sections for <a href="/image-tools#illustrations">Illustrations</a> and <a href="/storage#textures-patterns">Textures / Patterns</a> in Images.</p></li><li><p>Added sections in Linux for <a href="/linux-macos#linux-video">Video</a>, <a href="/linux-macos#linux-audio">Audio</a>, <a href="/linux-macos#linux-images">Images</a> and <a href="/linux-macos#file-tools">File Tools</a>.</p></li><li><p>Made a <a href="https://rentry.org/piracy" target="_blank" rel="noreferrer">&quot;safe for work&quot;</a> version of our index with no NSFW links listed.</p></li><li><p>Added a <a href="https://i.imgur.com/wnOXvKG.png" target="_blank" rel="noreferrer">collapsible list</a> of all the Tool sections to our site&#39;s sidebar.</p></li></ul><hr><h3 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h3><ul><li><p>Starred <a href="/video#multi-server">Streamflix</a> in Streaming Sites. Nice UI, fast 1080p, run by members of our community.</p></li><li><p>Starred <a href="/video#multi-server">watch.lonelil</a> in Streaming Sites. Nice UI, fast 4K + 1080p, live TV.</p></li><li><p>Starred <a href="/gaming#download-games">Game Bounty</a> in Game Download. Fast hosts, pre-installs, clean uploads, run by members of our community.</p></li><li><p>Starred <a href="/storage#abandonware-games">AbandonwareGames</a> in Abandonware Games. Nice site with a big library of old-school games.</p></li><li><p>Starred <a href="/gaming#steam-epic">Heroic Games Launcher</a> in Steam / Epic. Open-source Epic Games launcher.</p></li><li><p>Starred <a href="/downloading#download-directories">TG Archive</a> in Download Directories. Telegram file archive + search tool.</p></li><li><p>Starred <a href="/system-tools#system-debloating">BleachBit</a> in System Debloating. Popular system file cleaning tool.</p></li><li><p>Starred <a href="/video-tools#youtube-download">YT-DLP-GUI</a> in YouTube Download. Nice GUI for YT-DL with single-click installer.</p></li><li><p>Starred <a href="/system-tools#system-tweaks">EverythingToolbar</a> in System Tweaks. Adds lots of features to Windows toolbar.</p></li><li><p>Starred <a href="/text-tools#translators">DeepL</a> in Translators. People feel this gives some of the best results.</p></li><li><p>Starred <a href="/gaming#optimization-tools">Magpie</a> in Gaming Optimization. Enable AMD FSR on any game or device.</p></li><li><p>Starred <a href="/mobile#ios-apps">TrollStore</a> in iOS Apps. Permanently install non-App Store iOS apps w/o PC, paid dev account or being jailbroken.</p></li><li><p>Starred <a href="/video#smart-tv-firestick">SmartTube</a> in Smart TV / Firestick. Ad-free YouTube app. Previously called SmartTubeNext.</p></li></ul><hr><h3 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h3><ul><li><p>Removed NovaAI as they&#39;ve <a href="https://www.reddit.com/r/Piracy/comments/17pzrzj/nova_oss_the_api_that_provided_free_gpt4_and/" target="_blank" rel="noreferrer">decided to shut down</a>.</p></li><li><p>Removed both LocalCDN and Decentraleyes as they&#39;re redundant with <a href="https://blog.privacyguides.org/2021/12/01/firefox-privacy-2021-update/#localcdn-and-decentraleyes" target="_blank" rel="noreferrer">Total Cookie Protection</a> enabled.</p></li><li><p>Replaced all CurseForge links with Modrinth as people feel CurseForge <a href="https://youtu.be/Vhdwz5apiQQ?si=xgzkQFa1S7hZNa5-" target="_blank" rel="noreferrer">doesn&#39;t cooperate</a> with their user-base well.</p></li><li><p>Unstarred 12ft.io as it can no longer bypass non-JavaScript based paywalls.</p></li><li><p>Removed FileListing as they&#39;ve shut down their servers.</p></li><li><p>Removed GreaseMonkey as it hasn&#39;t been updated in 3 years + has a possible history of tracking users.</p></li></ul>',9))])}const S=i(p,[["render",h]]);export{y as __pageData,S as default};
